const trigger = $('When Executed by Another Workflow').first().json;
const urgencia = (trigger.urgencia || 'media').toLowerCase();

let emoji;
switch (urgencia) {
  case 'alta':
    emoji = '🚨🚨🚨';
    break;
  case 'media':
    emoji = '⚠️';
    break;
  case 'baixa':
    emoji = 'ℹ️';
    break;
  default:
    emoji = '⚠️';
}

// Link direto pra conversa no Chatwoot — troque a URL pela do seu Chatwoot
const link = `https://SEU-CHATWOOT.com/app/accounts/1/conversations/${trigger.conversation_id}`;

const texto = `${emoji} Lead pediu atendimento humano\n\n` +
  `👤 ${trigger.nome_lead}\n` +
  `📋 ${trigger.resumo}\n\n` +
  `🔗 ${link}`;

return [{ json: { texto } }];
